import { useCallback, useEffect, useRef, useState } from 'react'
import { Card, CardContent } from '@/components/ui/card'
import { Input } from '@/components/ui/input'

// ============================================================================
// Types
// ============================================================================

/** Compact customer shape returned by GET /customers (search response). */
export interface CustomerSelectorItem {
  id: string
  displayName: string
  type: 'private' | 'company'
  email?: string | null
  phone?: string | null
}

interface CustomerSearchResponse {
  customers: CustomerSelectorItem[]
}

// ============================================================================
// Props
// ============================================================================

export interface CustomerSelectorProps {
  /** Currently selected customer id (null = walk-in/anonymous). */
  customerId?: string | null
  /** Called when user selects a customer or chooses walk-in. */
  onSelect: (id: string | null) => void
  /** Whether a customer must be selected (walk-in not allowed). */
  required?: boolean
}

// ============================================================================
// Debounce hook — minimal inline implementation (250ms)
// ============================================================================

function useDebounce<T>(value: T, delayMs: number): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value)

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedValue(value), delayMs)
    return () => clearTimeout(timer)
  }, [value, delayMs])

  return debouncedValue
}

// ============================================================================
// Component — Customer Selector (autocomplete input)
// ============================================================================

export function CustomerSelector({
  customerId = null,
  onSelect,
  required = false,
}: CustomerSelectorProps) {
  // Search state
  const [query, setQuery] = useState('')
  const [results, setResults] = useState<CustomerSelectorItem[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [isOpen, setIsOpen] = useState(false)
  const [highlightIndex, setHighlightIndex] = useState(-1)

  // Cached selected customer (fetched on mount if customerId is set)
  const [selectedCustomerCache, setSelectedCustomerCache] = useState<CustomerSelectorItem | null>(null)

  // Debounced query (250ms delay before API call)
  const debouncedQuery = useDebounce(query, 250)

  // Refs for keyboard navigation and click-outside detection
  const inputRef = useRef<HTMLInputElement>(null)
  const dropdownRef = useRef<HTMLDivElement>(null)

  // ── Fetch selected customer on mount (if customerId is set) ──────

  useEffect(() => {
    if (!customerId) return

    let cancelled = false

    async function fetchSelectedCustomer() {
      try {
        const response = await fetch('/api/customers')
        if (response.ok) {
          const data: CustomerSearchResponse = await response.json()
          if (!cancelled) {
            const found = data.customers.find((c) => c.id === customerId)
            setSelectedCustomerCache(found ?? null)
          }
        }
      } catch {
        // Silently fail
      }
    }

    fetchSelectedCustomer()
    return () => { cancelled = true }
  }, [customerId])

  // ── Fetch customers on debounced query change ────────────────────

  useEffect(() => {
    // No search term → clear results, close dropdown
    if (!debouncedQuery || debouncedQuery.trim() === '') {
      setResults([])
      setIsOpen(false)
      return
    }

    let cancelled = false

    async function fetchCustomers() {
      setIsLoading(true)
      try {
        const response = await fetch(`/api/customers?search=${encodeURIComponent(debouncedQuery.trim())}`)
        if (response.ok) {
          const data: CustomerSearchResponse = await response.json()
          if (!cancelled) {
            setResults(data.customers.slice(0, 20))
            setIsOpen(true)
            setHighlightIndex(-1)
          }
        } else {
          if (!cancelled) {
            setResults([])
            setIsOpen(false)
          }
        }
      } catch {
        // Silently fail — walk-in is always available
        if (!cancelled) {
          setResults([])
          setIsOpen(false)
        }
      } finally {
        if (!cancelled) {
          setIsLoading(false)
        }
      }
    }

    fetchCustomers()
    return () => { cancelled = true }
  }, [debouncedQuery])

  // ── Click-outside handler — close dropdown when clicking outside ─

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (
        dropdownRef.current && !dropdownRef.current.contains(event.target as Node) &&
        inputRef.current && !inputRef.current.contains(event.target as Node)
      ) {
        setIsOpen(false)
      }
    }

    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  // ── Select a customer ────────────────────────────────────────────

  const handleSelectCustomer = useCallback((id: string | null) => {
    onSelect(id)
    setIsOpen(false)
    if (id === null) {
      // Reset to walk-in — clear input
      setQuery('')
      setResults([])
    }
  }, [onSelect])

  // ── Keyboard navigation ──────────────────────────────────────────

  const handleKeyDown = useCallback((e: React.KeyboardEvent<HTMLInputElement>) => {
    if (!isOpen || results.length === 0) return

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault()
        setHighlightIndex((prev) => Math.min(prev + 1, results.length - 1))
        break

      case 'ArrowUp':
        e.preventDefault()
        setHighlightIndex((prev) => Math.max(prev - 1, 0))
        break

      case 'Enter':
        e.preventDefault()
        if (highlightIndex >= 0 && highlightIndex < results.length) {
          handleSelectCustomer(results[highlightIndex].id)
        } else if (results.length === 1) {
          // Auto-select single result
          handleSelectCustomer(results[0].id)
        }
        break

      case 'Escape':
        e.preventDefault()
        setIsOpen(false)
        inputRef.current?.blur()
        break
    }
  }, [isOpen, results, highlightIndex, handleSelectCustomer])

  // ── Render helpers ───────────────────────────────────────────────

  // Prefer cached selected customer; fall back to searching in results
  const displaySelectedCustomer = selectedCustomerCache ?? results.find((c) => c.id === customerId) ?? null

  return (
    <Card>
      <CardContent className="p-4 space-y-3">
        {/* Label */}
        <label htmlFor="customer-search" className="text-sm font-medium text-muted-foreground">
          Customer {required && <span className="text-destructive">*</span>}
        </label>

        {/* Search input with dropdown */}
        <div ref={dropdownRef} className="relative">
          <Input
            id="customer-search"
            ref={inputRef}
            type="search"
            placeholder="Search customers..."
            value={query}
            onChange={(e) => {
              setQuery(e.target.value)
              setIsOpen(true)
              setHighlightIndex(-1)
            }}
            onFocus={() => {
              if (results.length > 0) setIsOpen(true)
            }}
            onKeyDown={handleKeyDown}
            className="w-full"
          />

          {/* Dropdown */}
          {isOpen && results.length > 0 && (
            <div className="absolute z-50 w-full mt-1 bg-popover border rounded-md shadow-lg max-h-64 overflow-y-auto">
              {/* Loading indicator */}
              {isLoading && (
                <div className="px-3 py-2 text-sm text-muted-foreground">Searching...</div>
              )}

              {/* Results list */}
              {!isLoading && results.map((customer, index) => (
                <button
                  key={customer.id}
                  type="button"
                  onClick={() => handleSelectCustomer(customer.id)}
                  onMouseEnter={() => setHighlightIndex(index)}
                  className={`w-full text-left px-3 py-2 text-sm transition-colors ${
                    index === highlightIndex
                      ? 'bg-accent text-accent-foreground'
                      : customerId === customer.id
                        ? 'bg-muted/50 font-medium'
                        : 'hover:bg-accent hover:text-accent-foreground'
                  }`}
                >
                  <div className="font-medium truncate">{customer.displayName}</div>
                  <div className="flex gap-3 text-xs text-muted-foreground mt-0.5">
                    {customer.email && (
                      <span className="truncate">{customer.email}</span>
                    )}
                    {customer.phone && (
                      <span className="truncate">{customer.phone}</span>
                    )}
                  </div>
                </button>
              ))}

              {/* No results within the loaded set */}
              {!isLoading && results.length === 0 && query.trim() !== '' && (
                <div className="px-3 py-2 text-sm text-muted-foreground">No customers found</div>
              )}
            </div>
          )}

          {/* Empty state hint — shown when input is focused but no results */}
          {isOpen && query.trim() !== '' && !isLoading && results.length === 0 && (
            <div className="absolute z-50 w-full mt-1 bg-popover border rounded-md shadow-lg px-3 py-2 text-sm text-muted-foreground">
              No customers found
            </div>
          )}
        </div>

        {/* Walk-in option — always visible */}
        <button
          type="button"
          onClick={() => handleSelectCustomer(null)}
          className={`w-full justify-start text-sm px-3 py-2 rounded-md border transition-colors ${
            customerId === null
              ? 'bg-primary text-primary-foreground border-transparent'
              : 'border-dashed border-input hover:bg-accent hover:text-accent-foreground'
          }`}
        >
          Walk-in (anonymous) {required && customerId === null && <span className="text-xs opacity-75">(no customer)</span>}
        </button>

        {/* Selected customer info */}
        {customerId !== null && displaySelectedCustomer && (
          <div className="pt-2 border-t text-xs text-muted-foreground space-y-0.5">
            <span className="font-medium">{displaySelectedCustomer.displayName}</span>
            {displaySelectedCustomer.email && <div>{displaySelectedCustomer.email}</div>}
            {displaySelectedCustomer.phone && <div>{displaySelectedCustomer.phone}</div>}
          </div>
        )}

        {/* Walk-in selected info */}
        {customerId === null && (
          <div className="pt-2 border-t text-xs text-muted-foreground italic">
            Anonymous sale — no customer attached
          </div>
        )}
      </CardContent>
    </Card>
  )
}

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { render, screen, fireEvent, waitFor, act } from '@testing-library/react'
import { CustomerSelector } from '../components/CustomerSelector'

// ── Mock fetch globally ────────────────────────────────────────────

function mockFetchCustomers(customers: Array<{ id: string; displayName: string; type: 'private' | 'company'; email?: string | null; phone?: string | null }>) {
  const mockFn = vi.fn().mockImplementation(async (url: string | URL | Request) => {
    const urlString = url.toString()
    if (urlString.includes('/api/customers')) {
      return {
        ok: true,
        json: async () => ({ customers }),
      } as Response
    }
    return { ok: false } as Response
  })
  vi.stubGlobal('fetch', mockFn)
}

function mockFetchError() {
  const mockFn = vi.fn().mockImplementation(async () => {
    return { ok: false } as Response
  })
  vi.stubGlobal('fetch', mockFn)
}

// ── Test data ──────────────────────────────────────────────────────

const mockCustomers = [
  { id: 'c1', displayName: 'Alice Smith', type: 'private' as const, email: 'alice@example.com', phone: '+32470123456' },
  { id: 'c2', displayName: 'Bob Jones', type: 'private' as const, email: 'bob@example.com', phone: null },
  { id: 'c3', displayName: 'Acme Corp', type: 'company' as const, email: 'info@acme.com', phone: '+3221234567' },
]

// ── Tests ──────────────────────────────────────────────────────────

describe('CustomerSelector (shared)', () => {
  let onSelect: ReturnType<typeof vi.fn>

  beforeEach(() => {
    onSelect = vi.fn()
  })

  afterEach(() => {
    vi.restoreAllMocks()
  })

  // ── Rendering ────────────────────────────────────────────────────

  it('renders with empty input and walk-in option on mount', () => {
    render(<CustomerSelector onSelect={onSelect} />)

    const input = screen.getByPlaceholderText(/search customers/i) as HTMLInputElement
    expect(input).toBeInTheDocument()
    expect(input.value).toBe('')

    // Walk-in button always visible
    expect(screen.getByText(/walk-in/i)).toBeInTheDocument()
  })

  it('shows no dropdown until user types', () => {
    render(<CustomerSelector onSelect={onSelect} />)

    const dropdown = screen.queryByRole('listbox')
    expect(dropdown).not.toBeInTheDocument()
  })

  // ── Selection callback ───────────────────────────────────────────

  it('calls onSelect with customer id when result is clicked', async () => {
    mockFetchCustomers(mockCustomers)
    render(<CustomerSelector onSelect={onSelect} />)

    const input = screen.getByPlaceholderText(/search customers/i) as HTMLInputElement

    await act(async () => {
      fireEvent.change(input, { target: { value: 'alice' } })
    })

    // Wait for debounce + fetch to complete
    await waitFor(() => {
      expect(screen.getByText('Alice Smith')).toBeInTheDocument()
    }, { timeout: 1000 })

    // Click on Alice Smith result
    await act(async () => {
      fireEvent.click(screen.getByText('Alice Smith'))
    })

    expect(onSelect).toHaveBeenCalledWith('c1')
  }, 5000)

  it('calls onSelect(null) when walk-in is selected', async () => {
    render(<CustomerSelector customerId="c1" onSelect={onSelect} />)

    const walkInBtn = screen.getByText(/walk-in/i) as HTMLButtonElement

    await act(async () => {
      fireEvent.click(walkInBtn)
    })

    expect(onSelect).toHaveBeenCalledWith(null)
  })

  // ── Debounce behavior ────────────────────────────────────────────

  it('does not fetch immediately — waits for debounce delay', async () => {
    mockFetchCustomers(mockCustomers)
    render(<CustomerSelector onSelect={onSelect} />)

    const input = screen.getByPlaceholderText(/search customers/i) as HTMLInputElement

    // Type a character
    await act(async () => {
      fireEvent.change(input, { target: { value: 'alice' } })
    })

    // Should not have fetched yet (debounce delay of 250ms)
    expect(fetch).not.toHaveBeenCalled()

    // Wait for debounce + fetch to complete
    await waitFor(() => {
      expect(fetch).toHaveBeenCalledWith(expect.stringContaining('/api/customers?search=alice'))
    }, { timeout: 500 })
  }, 10000)

  it('fetches customers after debounce delay', async () => {
    mockFetchCustomers(mockCustomers)
    render(<CustomerSelector onSelect={onSelect} />)

    const input = screen.getByPlaceholderText(/search customers/i) as HTMLInputElement

    await act(async () => {
      fireEvent.change(input, { target: { value: 'alice' } })
    })

    // Wait for debounce + fetch to complete
    await waitFor(() => {
      expect(fetch).toHaveBeenCalledWith(expect.stringContaining('/api/customers?search=alice'))
    }, { timeout: 500 })

    // Results should be visible
    await waitFor(() => {
      expect(screen.getByText('Alice Smith')).toBeInTheDocument()
    }, { timeout: 1000 })
  }, 10000)

  // ── Keyboard navigation ──────────────────────────────────────────

  it('highlights results with ArrowDown/ArrowUp', async () => {
    mockFetchCustomers(mockCustomers)
    render(<CustomerSelector onSelect={onSelect} />)

    const input = screen.getByPlaceholderText(/search customers/i) as HTMLInputElement

    await act(async () => {
      fireEvent.change(input, { target: { value: 'a' } })
    })

    // Wait for debounce + fetch to complete
    await waitFor(() => {
      expect(screen.getByText('Alice Smith')).toBeInTheDocument()
    }, { timeout: 1000 })

    // Navigate down (from -1 → 0, Alice highlighted)
    await act(async () => {
      fireEvent.keyDown(input, { key: 'ArrowDown' })
    })

    const aliceBtn = screen.getByText('Alice Smith').closest('button')
    expect(aliceBtn).toHaveClass('bg-accent')

    // Navigate down again (from 0 → 1, Bob highlighted)
    await act(async () => {
      fireEvent.keyDown(input, { key: 'ArrowDown' })
    })

    const bobBtn = screen.getByText('Bob Jones').closest('button')
    expect(bobBtn).toHaveClass('bg-accent')

    // Navigate up (from 1 → 0, Alice highlighted again)
    await act(async () => {
      fireEvent.keyDown(input, { key: 'ArrowUp' })
    })

    const aliceBtn2 = screen.getByText('Alice Smith').closest('button')
    expect(aliceBtn2).toHaveClass('bg-accent')
  }, 5000)

  it('selects customer with Enter key when highlighted', async () => {
    mockFetchCustomers(mockCustomers)
    render(<CustomerSelector onSelect={onSelect} />)

    const input = screen.getByPlaceholderText(/search customers/i) as HTMLInputElement

    await act(async () => {
      fireEvent.change(input, { target: { value: 'a' } })
    })

    // Wait for debounce + fetch to complete
    await waitFor(() => {
      expect(screen.getByText('Alice Smith')).toBeInTheDocument()
    }, { timeout: 1000 })

    // Navigate to Bob Jones (index 1)
    await act(async () => {
      fireEvent.keyDown(input, { key: 'ArrowDown' })
    })
    await act(async () => {
      fireEvent.keyDown(input, { key: 'ArrowDown' })
    })

    // Press Enter to select
    await act(async () => {
      fireEvent.keyDown(input, { key: 'Enter' })
    })

    expect(onSelect).toHaveBeenCalledWith('c2')
  }, 5000)

  it('auto-selects when only one result matches and Enter pressed', async () => {
    mockFetchCustomers([{ id: 'c1', displayName: 'Alice Smith', type: 'private' as const, email: 'alice@example.com', phone: null }])
    render(<CustomerSelector onSelect={onSelect} />)

    const input = screen.getByPlaceholderText(/search customers/i) as HTMLInputElement

    await act(async () => {
      fireEvent.change(input, { target: { value: 'alice' } })
    })

    // Wait for debounce + fetch to complete
    await waitFor(() => {
      expect(screen.getByText('Alice Smith')).toBeInTheDocument()
    }, { timeout: 1000 })

    // Single result should be auto-selected on Enter
    await act(async () => {
      fireEvent.keyDown(input, { key: 'Enter' })
    })

    expect(onSelect).toHaveBeenCalledWith('c1')
  }, 5000)

  it('closes dropdown on Escape key', async () => {
    mockFetchCustomers(mockCustomers)
    render(<CustomerSelector onSelect={onSelect} />)

    const input = screen.getByPlaceholderText(/search customers/i) as HTMLInputElement

    await act(async () => {
      fireEvent.change(input, { target: { value: 'a' } })
    })

    // Wait for debounce + fetch to complete
    await waitFor(() => {
      expect(screen.getByText('Alice Smith')).toBeInTheDocument()
    }, { timeout: 1000 })

    // Press Escape
    await act(async () => {
      fireEvent.keyDown(input, { key: 'Escape' })
    })

    // Dropdown should close (results hidden)
    await waitFor(() => {
      expect(screen.queryByText('Alice Smith')).not.toBeInTheDocument()
    }, { timeout: 1000 })
  }, 5000)

  // ── Controlled customerId prop ───────────────────────────────────

  it('displays selected customer info when customerId is provided', async () => {
    mockFetchCustomers(mockCustomers)
    render(<CustomerSelector customerId="c1" onSelect={onSelect} />)

    // Wait for any pending state updates to flush and fetch to complete
    await waitFor(() => {
      expect(screen.getByText('Alice Smith')).toBeInTheDocument()
    }, { timeout: 5000 })
  })

  it('shows anonymous message when customerId is null', async () => {
    render(<CustomerSelector customerId={null} onSelect={onSelect} />)

    await waitFor(() => {
      expect(screen.getByText(/anonymous sale/i)).toBeInTheDocument()
    }, { timeout: 3000 })
  })

  // ── Error handling ───────────────────────────────────────────────

  it('handles fetch errors gracefully', async () => {
    mockFetchError()
    render(<CustomerSelector onSelect={onSelect} />)

    const input = screen.getByPlaceholderText(/search customers/i) as HTMLInputElement

    await act(async () => {
      fireEvent.change(input, { target: { value: 'test' } })
    })

    // Wait for debounce + fetch to complete (should fail silently)
    await waitFor(() => {
      expect(fetch).toHaveBeenCalled()
    }, { timeout: 500 })

    // Should not crash — just show no results
    expect(onSelect).not.toHaveBeenCalled()
  }, 5000)

  // ── Required prop ────────────────────────────────────────────────

  it('shows required indicator when required is true', () => {
    render(<CustomerSelector onSelect={onSelect} required />)

    // Label contains "Customer" with asterisk
    const label = screen.getByLabelText(/customer/i) as HTMLInputElement
    expect(label).toBeInTheDocument()
    // The asterisk should be present in the DOM
    const asterisk = screen.queryByText('*')
    expect(asterisk).toBeInTheDocument()
  })

  it('walk-in button shows warning when required is true and walk-in selected', () => {
    render(<CustomerSelector customerId={null} onSelect={onSelect} required />)

    const walkInBtn = screen.getByText(/walk-in/i)
    expect(walkInBtn).toBeInTheDocument()
  })
})

